@inline function _nas_shape_kg_env_bool(key::AbstractString, default::Bool=false)
    raw = lowercase(strip(get(ENV, key, default ? "true" : "false")))
    return raw in ("1", "true", "yes", "on")
end

@inline function _nas_shape_kg_law_from_env(key::AbstractString, default::Symbol)
    raw = lowercase(strip(get(ENV, key, String(default))))
    raw == "shape_laminate14" && return :shape_laminate14
    raw == "laminate14" && return :shape_laminate14
    raw == "shape11" && return :shape11
    return default
end

@inline function _nas_shape_kg_poly_weight(weight::Symbol, r::Float64, s::Float64)
    weight === :one && return 1.0
    weight === :r && return r
    weight === :s && return s
    weight === :rs && return r * s
    weight === :r2 && return r * r
    weight === :s2 && return s * s
    return 0.0
end

@inline function _nas_shape_kg_deriv_value(deriv::Symbol,
                                           dNidx::Float64, dNidy::Float64,
                                           dNjdx::Float64, dNjdy::Float64)
    deriv === :xx && return dNidx * dNjdx
    deriv === :yy && return dNidy * dNjdy
    deriv === :xy && return dNidx * dNjdy + dNidy * dNjdx
    return 0.0
end

@inline function _nas_shape_kg_add_block!(K::AbstractMatrix, block::Symbol,
                                          i::Int, j::Int, val::Float64)
    if block === :uu
        K[3 * (i - 1) + 1, 3 * (j - 1) + 1] += val
    elseif block === :vv
        K[3 * (i - 1) + 2, 3 * (j - 1) + 2] += val
    elseif block === :ww
        K[3 * (i - 1) + 3, 3 * (j - 1) + 3] += val
    elseif block === :uv
        K[3 * (i - 1) + 1, 3 * (j - 1) + 2] += val
        K[3 * (i - 1) + 2, 3 * (j - 1) + 1] += val
    elseif block === :uw
        K[3 * (i - 1) + 1, 3 * (j - 1) + 3] += val
        K[3 * (i - 1) + 3, 3 * (j - 1) + 1] += val
    elseif block === :vw
        K[3 * (i - 1) + 2, 3 * (j - 1) + 3] += val
        K[3 * (i - 1) + 3, 3 * (j - 1) + 2] += val
    end
    return K
end

function _nas_shape_kg_term_parts(term::Symbol)
    raw = String(term)
    a = findfirst('_', raw)
    b = findnext('_', raw, a + 1)
    return Symbol(raw[1:a-1]), Symbol(raw[a+1:b-1]), Symbol(raw[b+1:end])
end

function _nas_shape_kg_candidate(coords::AbstractMatrix, term::Symbol)
    block, deriv, weight = _nas_shape_kg_term_parts(term)
    gp = ((-sqrt(3.0 / 5.0), 5.0 / 9.0), (0.0, 8.0 / 9.0), (sqrt(3.0 / 5.0), 5.0 / 9.0))
    K = zeros(12, 12)
    @inbounds for (r, wr) in gp, (s, ws) in gp
        dNr = (-0.25 * (1.0 - s), 0.25 * (1.0 - s), 0.25 * (1.0 + s), -0.25 * (1.0 + s))
        dNs = (-0.25 * (1.0 - r), -0.25 * (1.0 + r), 0.25 * (1.0 + r), 0.25 * (1.0 - r))
        J11 = sum(dNr[i] * coords[i, 1] for i in 1:4)
        J12 = sum(dNr[i] * coords[i, 2] for i in 1:4)
        J21 = sum(dNs[i] * coords[i, 1] for i in 1:4)
        J22 = sum(dNs[i] * coords[i, 2] for i in 1:4)
        detJ = J11 * J22 - J12 * J21
        abs(detJ) > 1e-300 || continue
        inv_det = 1.0 / detJ
        iJ11 = J22 * inv_det
        iJ12 = -J12 * inv_det
        iJ21 = -J21 * inv_det
        iJ22 = J11 * inv_det
        q = wr * ws * abs(detJ) * _nas_shape_kg_poly_weight(weight, r, s)
        for i in 1:4, j in 1:4
            dNidx = iJ11 * dNr[i] + iJ12 * dNs[i]
            dNidy = iJ21 * dNr[i] + iJ22 * dNs[i]
            dNjdx = iJ11 * dNr[j] + iJ12 * dNs[j]
            dNjdy = iJ21 * dNr[j] + iJ22 * dNs[j]
            _nas_shape_kg_add_block!(K, block, i, j,
                q * _nas_shape_kg_deriv_value(deriv, dNidx, dNidy, dNjdx, dNjdy))
        end
    end
    return K
end

function _nas_shape_kg_metrics(coords::AbstractMatrix, Cb)
    e12x = Float64(coords[2, 1] - coords[1, 1])
    e12y = Float64(coords[2, 2] - coords[1, 2])
    e23x = Float64(coords[3, 1] - coords[2, 1])
    e23y = Float64(coords[3, 2] - coords[2, 2])
    e34x = Float64(coords[4, 1] - coords[3, 1])
    e34y = Float64(coords[4, 2] - coords[3, 2])
    e41x = Float64(coords[1, 1] - coords[4, 1])
    e41y = Float64(coords[1, 2] - coords[4, 2])
    l12 = hypot(e12x, e12y)
    l23 = hypot(e23x, e23y)
    l34 = hypot(e34x, e34y)
    l41 = hypot(e41x, e41y)
    lx_edge = max(l12, l34)
    ly_edge = 0.5 * (l23 + l41)
    ly_span = maximum(@view coords[:, 2]) - minimum(@view coords[:, 2])
    lx = lx_edge
    ly = ly_span > 1e-12 ? ly_span : ly_edge
    aspect = max(lx, ly) / max(min(lx, ly), 1e-300)
    skew = abs(e12x * (-e41x) + e12y * (-e41y)) / max(l12 * l41, 1e-300)
    taper = abs(l23 - l41) / max(0.5 * (l23 + l41), 1e-300)
    beta = 0.0
    gamma = 0.0
    delta = 0.0
    if Cb !== nothing
        D11 = Float64(Cb[1, 1])
        D22 = Float64(Cb[2, 2])
        D12 = Float64(Cb[1, 2])
        D66 = Float64(Cb[3, 3])
        D16 = Float64(Cb[1, 3])
        D26 = Float64(Cb[2, 3])
        if D11 > 0.0 && D22 > 0.0
            beta = (D12 + 2.0 * D66) / sqrt(D11 * D22)
            gamma = D16 / ((D11^3 * D22)^(1.0 / 4.0))
            delta = D26 / ((D11 * D22^3)^(1.0 / 4.0))
        end
    end
    return (; aspect, skew, taper, beta, gamma, delta)
end

@inline function _nas_shape_kg_feature_values(features, m)
    aspect = m.aspect
    aspect2 = aspect * aspect
    inv_aspect = 1.0 / max(aspect, 1e-300)
    inv_aspect2 = 1.0 / max(aspect2, 1e-300)
    values = Float64[]
    for feature in features
        if feature === :one
            push!(values, 1.0)
        elseif feature === :aspect
            push!(values, aspect)
        elseif feature === :aspect2
            push!(values, aspect2)
        elseif feature === :inv_aspect
            push!(values, inv_aspect)
        elseif feature === :inv_aspect2
            push!(values, inv_aspect2)
        elseif feature === :skew
            push!(values, m.skew)
        elseif feature === :skew_aspect
            push!(values, m.skew * aspect)
        elseif feature === :skew_aspect2
            push!(values, m.skew * aspect2)
        elseif feature === :taper
            push!(values, m.taper)
        elseif feature === :taper_aspect
            push!(values, m.taper * aspect)
        elseif feature === :taper_aspect2
            push!(values, m.taper * aspect2)
        elseif feature === :nemeth_beta
            push!(values, m.beta)
        elseif feature === :nemeth_gamma
            push!(values, m.gamma)
        elseif feature === :nemeth_delta
            push!(values, m.delta)
        else
            push!(values, 0.0)
        end
    end
    return values
end

function _nas_shape_kg_eval_component!(K12::AbstractMatrix, coords::AbstractMatrix,
                                       component::Symbol, law::Symbol,
                                       resultant::Float64, metrics)
    key = (component, law)
    haskey(_NAS_SHAPE_KG_COEFFS, key) || return K12
    features = law === :shape_laminate14 ? _NAS_SHAPE_LAMINATE14_FEATURES : _NAS_SHAPE11_FEATURES
    values = _nas_shape_kg_feature_values(features, metrics)
    cache = Dict{Symbol,Matrix{Float64}}()
    for (term, coeffs) in _NAS_SHAPE_KG_COEFFS[key]
        c = 0.0
        @inbounds for i in eachindex(values)
            c += Float64(coeffs[i]) * values[i]
        end
        abs(c) > 0.0 || continue
        candidate = get!(cache, term) do
            _nas_shape_kg_candidate(coords, term)
        end
        K12 .+= (resultant * c) .* candidate
    end
    return K12
end

function geometric_stiffness_quad4_nastran_shape11_synth(coords::AbstractMatrix,
                                                          sigma_mem::AbstractVector,
                                                          h::Float64,
                                                          Cb=nothing)
    Kg = zeros(24, 24)
    h > 1e-30 || return Kg
    metrics = _nas_shape_kg_metrics(coords, Cb)
    nxx_law = _nas_shape_kg_law_from_env("JFEM_SOL105_KG_SHAPE11_NXX_LAW", :shape11)
    nyy_law = _nas_shape_kg_law_from_env("JFEM_SOL105_KG_SHAPE11_NYY_LAW", :shape11)
    nxy_law = _nas_shape_kg_law_from_env("JFEM_SOL105_KG_SHAPE11_NXY_LAW", :shape11)
    if _nas_shape_kg_env_bool("JFEM_SOL105_KG_SHAPE11_LAMINATE_NXX", false)
        nxx_law = :shape_laminate14
    end
    K12 = zeros(12, 12)
    _nas_shape_kg_eval_component!(K12, coords, :nxx, nxx_law, Float64(sigma_mem[1]) * h, metrics)
    _nas_shape_kg_eval_component!(K12, coords, :nyy, nyy_law, Float64(sigma_mem[2]) * h, metrics)
    _nas_shape_kg_eval_component!(K12, coords, :nxy, nxy_law, Float64(sigma_mem[3]) * h, metrics)
    tdofs = (1, 2, 3, 7, 8, 9, 13, 14, 15, 19, 20, 21)
    @inbounds for a in 1:12, b in 1:12
        Kg[tdofs[a], tdofs[b]] = K12[a, b]
    end
    return Kg
end

function geometric_stiffness_quad4_nastran_shape11_synth(coords::AbstractMatrix,
                                                          sigma_mem_gp::AbstractMatrix,
                                                          h::Float64,
                                                          Cb=nothing)
    size(sigma_mem_gp, 2) >= 3 || return zeros(24, 24)
    inv_ngp = 1.0 / max(size(sigma_mem_gp, 1), 1)
    sigma_mem = [
        sum(@view sigma_mem_gp[:, 1]) * inv_ngp,
        sum(@view sigma_mem_gp[:, 2]) * inv_ngp,
        sum(@view sigma_mem_gp[:, 3]) * inv_ngp,
    ]
    return geometric_stiffness_quad4_nastran_shape11_synth(coords, sigma_mem, h, Cb)
end
